package dev.doughbay.fabric;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import static dev.doughbay.fabric.AutomaticReportDetector.*;
class AutomaticReportPayloadTest {
 @Test void newRecoveryKindRequiresItsExactAdvertisedSignature()throws Exception{var caps=new ObjectMapper().readTree("{\"schemaVersions\":[1,2,3],\"configured\":true,\"requiresAuthentication\":false,\"maxBodyBytes\":65536,\"automaticReports\":{\"supported\":true,\"grouped\":true,\"schemaVersion\":3,\"kinds\":[\"AUTOMATIC_RECOVERY_STALLED\"]}}");assertFalse(BugReportTransport.advertisesAutomaticReports(caps,Failure.AUTOMATIC_RECOVERY_STALLED));((com.fasterxml.jackson.databind.node.ObjectNode)caps.path("automaticReports")).putObject("signatures").putArray("AUTOMATIC_RECOVERY_STALLED").add("EVASION_RESUME_STALLED");assertTrue(BugReportTransport.advertisesAutomaticReports(caps,Failure.AUTOMATIC_RECOVERY_STALLED));}
 @Test void recoveryFingerprintMatchesTheReceiverGoldenVector(){assertEquals("3448f4404f4a66d654fba2568d22156b0d446394b6cf1e3ba07c7ad605a57c7c",AutomaticReportMetadata.of("0.1.0","26.2",new Candidate(Failure.AUTOMATIC_RECOVERY_STALLED,Signature.EVASION_RESUME_STALLED)).fingerprint());}
 @Test void recoveryMetadataUsesOnlyItsClosedSignatureAndExistingFingerprintContract()throws Exception{var a=AutomaticReportMetadata.of("0.1.0","26.2",new Candidate(Failure.AUTOMATIC_RECOVERY_STALLED,Signature.EVASION_RESUME_STALLED));var p=new BugReportPayload("0.1.0","26.2",a.description(),a.expected(),BugReportDiagnostics.counters(""));var j=new ObjectMapper().readTree(p.json("",a));assertEquals("AUTOMATIC_RECOVERY_STALLED",j.path("automatic").path("kind").asText());assertEquals("EVASION_RESUME_STALLED",j.path("automatic").path("signature").asText());assertTrue(a.description().contains("five additional minutes"));assertThrows(IllegalArgumentException.class,()->new AutomaticReportMetadata(Failure.DURABLE_WRITE_REJECTED,Signature.EVASION_RESUME_STALLED,"0".repeat(64)));assertThrows(IllegalArgumentException.class,()->new AutomaticReportMetadata(Failure.AUTOMATIC_RECOVERY_STALLED,Signature.CHECKPOINT_REJECTED,"0".repeat(64)));}
 static AutomaticReportMetadata metadata(String build){return AutomaticReportMetadata.of(build,"26.2",new Candidate(Failure.DURABLE_WRITE_REJECTED,Signature.IMMUTABLE_POSITION_IDENTITY_CONFLICT));}
 static BugReportPayload payload(){var a=metadata("0.1.0");return new BugReportPayload("0.1.0","26.2",a.description(),a.expected(),BugReportDiagnostics.counters(""));}
 @Test void anonymousFingerprintIsStableAcrossReportersButChangesByBuild(){assertEquals(metadata("0.1.0"),metadata("0.1.0"));assertNotEquals(metadata("0.1.0").fingerprint(),metadata("0.1.1").fingerprint());}
 @Test void schemaThreeAddsOnlyValidatedGroupingFields()throws Exception{var json=new ObjectMapper().readTree(payload().json("",metadata("0.1.0")));assertEquals(3,json.path("schemaVersion").asInt());assertEquals(8,json.size());SettingsCode.validateReportCode(json.path("settingsCode").asText());assertEquals(3,json.path("automatic").size());assertEquals(metadata("0.1.0").fingerprint(),json.path("automatic").path("fingerprint").asText());}
 @Test void manualSchemasRemainUnchanged()throws Exception{var json=new ObjectMapper();assertEquals(1,json.readTree(payload().json()).path("schemaVersion").asInt());assertEquals(2,json.readTree(payload().json(BugReportLog.sanitize(""))).path("schemaVersion").asInt());}
 @Test void forgedFingerprintOrPrivateAutomaticDescriptionIsRefused(){var bad=new AutomaticReportMetadata(Failure.DURABLE_WRITE_REJECTED,Signature.IMMUTABLE_POSITION_IDENTITY_CONFLICT,"0".repeat(64));assertThrows(IllegalArgumentException.class,()->payload().json("",bad));var p=new BugReportPayload("0.1.0","26.2","PrivatePlayer is having a problem",metadata("0.1.0").expected(),BugReportDiagnostics.counters(""));assertThrows(IllegalArgumentException.class,()->p.json("",metadata("0.1.0")));}
 @Test void existingManualReceiverCannotReceiveAutomaticReports()throws Exception{var caps=new ObjectMapper().readTree("{\"schemaVersions\":[1,2],\"configured\":true,\"requiresAuthentication\":false}");assertThrows(IllegalStateException.class,()->BugReportTransport.automaticRequest(payload(),"retry-key-123","",metadata("0.1.0"),caps));}
 @Test void groupedCapabilitiesPermitOnlyTheAdvertisedKindWithoutAuthorization()throws Exception{var caps=new ObjectMapper().readTree("{\"schemaVersions\":[1,2,3],\"configured\":true,\"requiresAuthentication\":false,\"maxBodyBytes\":65536,\"automaticReports\":{\"supported\":true,\"grouped\":true,\"schemaVersion\":3,\"kinds\":[\"DURABLE_WRITE_REJECTED\"]}}");var req=BugReportTransport.automaticRequest(payload(),"retry-key-123","",metadata("0.1.0"),caps);assertEquals("https://gonuts.at/v1/bugs",req.uri().toString());assertTrue(req.headers().firstValue("Authorization").isEmpty());assertFalse(BugReportTransport.advertisesAutomaticReports(caps,Failure.PERSISTENCE_WRITER_FAILED));}
}
